-- Orbit Postgres baseline: generated from the SQLite schema at migration version 46
-- (apps/server/migrations/0001..0046) and applied in place of those migrations on a new Postgres
-- database, recorded as version 46. Every later migration needs a Postgres twin in this directory.
--
-- Conventions (the server talks to both backends through the sqlx `Any` driver):
-- * Every SQLite INTEGER is BIGINT, including 0/1 flags (no BOOLEAN anywhere); BLOB is BYTEA.
-- * SQLite rowid-alias primary keys are `BIGINT GENERATED BY DEFAULT AS IDENTITY`. After copying
--   rows with explicit ids, move the sequence: SELECT setval(pg_get_serial_sequence(t, c), max(c)).
-- * Table, column, index, constraint and trigger names are the SQLite ones. Each SQLite trigger
--   is a plpgsql function `<trigger>_fn()` plus a trigger of the same name; RAISE(ABORT, msg)
--   is RAISE EXCEPTION with the identical message (SQLSTATE P0001).
-- * Postgres fires same-event triggers in name order, SQLite newest first. Where both could
--   raise for the same row, the first Postgres trigger also performs the check SQLite would
--   have run first, so the error message is the same (see the comments at those triggers).
-- * Trigger WHEN clauses with subqueries are tested inside the function (Postgres does not
--   allow subqueries in WHEN).
-- * FTS5 tables page_search and chat_search are plain tables with a generated tsvector column
--   in the `orbit_search` configuration (unaccent + simple, like unicode61 remove_diacritics).
-- * The database must use code-point text order and Unicode case rules, like SQLite:
--   CREATE DATABASE ... TEMPLATE template0 LOCALE_PROVIDER builtin BUILTIN_LOCALE 'C.UTF-8'
--   LOCALE 'C.UTF-8'. `Database::open` refuses other databases.
-- * Text comparisons in the schema that depend on ordering use COLLATE "C" (SQLite BINARY).

-- Search text: lower case and no diacritics, like FTS5 unicode61 remove_diacritics.
CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE TEXT SEARCH CONFIGURATION orbit_search (COPY = simple);
ALTER TEXT SEARCH CONFIGURATION orbit_search
    ALTER MAPPING FOR hword, hword_part, word WITH unaccent, simple;

-- SQLite json_valid(): true for well-formed JSON text, NULL for NULL, never an error.
CREATE FUNCTION orbit_json_valid(value TEXT) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE STRICT AS $$
BEGIN
    PERFORM value::json;
    RETURN TRUE;
EXCEPTION WHEN others THEN
    RETURN FALSE;
END;
$$;

CREATE TABLE installation_state (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (id = 1),
    initialized BIGINT NOT NULL DEFAULT 0 CHECK (initialized IN (0, 1)),
    initialized_at BIGINT
, root_user_id TEXT);
CREATE TABLE jobs (
    id TEXT PRIMARY KEY,
    workspace_id TEXT,
    schedule_id TEXT,
    scheduled_for BIGINT,
    manual_retry_of TEXT REFERENCES jobs(id) ON DELETE SET NULL,
    kind TEXT NOT NULL,
    payload_json TEXT NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('queued', 'running', 'succeeded', 'failed', 'dead')),
    priority TEXT NOT NULL DEFAULT 'normal'
        CHECK (priority IN ('low', 'normal', 'high', 'critical')),
    attempt_count BIGINT NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    max_attempts BIGINT NOT NULL CHECK (max_attempts > 0),
    available_at BIGINT NOT NULL,
    lease_owner TEXT,
    claim_token TEXT,
    lease_expires_at BIGINT,
    last_error TEXT,
    dead_at BIGINT,
    incident_hold BIGINT NOT NULL DEFAULT 0 CHECK (incident_hold IN (0, 1)),
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    UNIQUE (schedule_id, scheduled_for)
);
CREATE INDEX jobs_claimable
    ON jobs (state, available_at, lease_expires_at);
CREATE TABLE job_attempts (
    job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    attempt BIGINT NOT NULL CHECK (attempt > 0),
    started_at BIGINT NOT NULL,
    finished_at BIGINT,
    outcome TEXT,
    error TEXT,
    PRIMARY KEY (job_id, attempt)
);
CREATE TABLE schedules (
    id TEXT PRIMARY KEY,
    workspace_id TEXT,
    job_kind TEXT NOT NULL,
    payload_json TEXT NOT NULL,
    schedule TEXT NOT NULL,
    next_run_at BIGINT NOT NULL,
    last_materialized_at BIGINT,
    catch_up_mode TEXT NOT NULL DEFAULT 'latest'
        CHECK (catch_up_mode IN ('latest', 'full')),
    consecutive_failures BIGINT NOT NULL DEFAULT 0 CHECK (consecutive_failures >= 0),
    enabled BIGINT NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    updated_at BIGINT NOT NULL
);
ALTER TABLE jobs ADD CONSTRAINT jobs_schedule_id_fkey
    FOREIGN KEY (schedule_id) REFERENCES schedules(id) ON DELETE SET NULL;
CREATE INDEX schedules_due ON schedules (enabled, next_run_at);
CREATE TABLE audit_events (
    id TEXT PRIMARY KEY,
    workspace_id TEXT,
    actor_id TEXT,
    action TEXT NOT NULL,
    outcome TEXT NOT NULL,
    resource_type TEXT NOT NULL,
    resource_id TEXT,
    request_id TEXT NOT NULL,
    metadata_json TEXT NOT NULL,
    occurred_at BIGINT NOT NULL
);
CREATE INDEX audit_events_workspace_time
    ON audit_events (workspace_id, occurred_at);
CREATE TABLE outbox_events (
    id TEXT PRIMARY KEY,
    scope TEXT NOT NULL,
    sequence BIGINT NOT NULL CHECK (sequence > 0),
    workspace_id TEXT,
    topic TEXT NOT NULL,
    payload_json TEXT NOT NULL,
    created_at BIGINT NOT NULL,
    published_at BIGINT,
    UNIQUE (scope, sequence)
);
CREATE INDEX outbox_events_unpublished
    ON outbox_events (published_at, created_at);
CREATE TABLE attachment_blobs (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL,
    sha256 TEXT NOT NULL,
    byte_size BIGINT NOT NULL CHECK (byte_size >= 0),
    storage_key TEXT NOT NULL,
    created_at BIGINT NOT NULL,
    quarantine_until BIGINT NOT NULL,
    UNIQUE (workspace_id, sha256, byte_size),
    UNIQUE (storage_key)
);
CREATE TABLE pending_uploads (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    temporary_path TEXT NOT NULL,
    original_name TEXT NOT NULL,
    media_type TEXT NOT NULL,
    byte_size BIGINT NOT NULL CHECK (byte_size >= 0),
    sha256 TEXT,
    state TEXT NOT NULL CHECK (state IN ('receiving', 'staged', 'complete', 'failed')),
    created_at BIGINT NOT NULL,
    expires_at BIGINT NOT NULL,
    completed_at BIGINT
);
CREATE INDEX pending_uploads_expiry
    ON pending_uploads (state, expires_at);
CREATE TABLE users (
    id TEXT PRIMARY KEY,
    email TEXT NOT NULL,
    normalized_email TEXT NOT NULL UNIQUE,
    display_name TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    installation_admin BIGINT NOT NULL DEFAULT 0 CHECK (installation_admin IN (0, 1)),
    suspended_at BIGINT,
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL
, email_verified_at BIGINT, title TEXT CHECK (title IS NULL OR length(title) BETWEEN 1 AND 80), pronouns TEXT CHECK (pronouns IS NULL OR length(pronouns) BETWEEN 1 AND 40), timezone TEXT CHECK (timezone IS NULL OR length(timezone) BETWEEN 1 AND 64), bio TEXT CHECK (bio IS NULL OR length(bio) BETWEEN 1 AND 500), phone TEXT CHECK (phone IS NULL OR length(phone) BETWEEN 1 AND 32));
ALTER TABLE installation_state ADD CONSTRAINT installation_state_root_user_id_fkey
    FOREIGN KEY (root_user_id) REFERENCES users(id);
CREATE TABLE workspaces (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    deleted_at BIGINT,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL
, owner_membership_id TEXT);
CREATE TABLE memberships (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'member')),
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    UNIQUE (workspace_id, user_id)
);
ALTER TABLE workspaces ADD CONSTRAINT workspaces_owner_membership_id_fkey
    FOREIGN KEY (owner_membership_id) REFERENCES memberships(id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE projects (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    project_key TEXT NOT NULL,
    color TEXT NOT NULL,
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    deleted_at BIGINT,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL, restore_project_key TEXT, auto_close_parent BIGINT NOT NULL DEFAULT 1
    CHECK (auto_close_parent IN (0, 1)), auto_close_sub_issues BIGINT NOT NULL DEFAULT 1
    CHECK (auto_close_sub_issues IN (0, 1)), task_counter BIGINT NOT NULL DEFAULT 0 CHECK (task_counter >= 0),
    UNIQUE (workspace_id, project_key)
);
CREATE TABLE setup_tokens (
    token_hash BYTEA PRIMARY KEY CHECK (octet_length(token_hash) = 32),
    expires_at BIGINT NOT NULL,
    created_at BIGINT NOT NULL
);
CREATE TABLE recovery_tokens (
    token_hash BYTEA PRIMARY KEY CHECK (octet_length(token_hash) = 32),
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    expires_at BIGINT NOT NULL,
    created_at BIGINT NOT NULL
);
CREATE TABLE sessions (
    id TEXT PRIMARY KEY,
    token_hash BYTEA NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at BIGINT NOT NULL,
    last_activity_at BIGINT NOT NULL,
    idle_expires_at BIGINT NOT NULL,
    absolute_expires_at BIGINT NOT NULL,
    revoked_at BIGINT
);
CREATE INDEX sessions_user_active ON sessions (user_id, revoked_at, idle_expires_at);
CREATE INDEX recovery_tokens_expiry ON recovery_tokens (expires_at);
CREATE TABLE attachment_references (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL,
    task_id TEXT NOT NULL,
    comment_id TEXT,
    owner_id TEXT NOT NULL,
    blob_id TEXT NOT NULL REFERENCES attachment_blobs(id) ON DELETE RESTRICT,
    display_name TEXT NOT NULL,
    media_type TEXT NOT NULL,
    byte_size BIGINT NOT NULL CHECK (byte_size >= 0),
    created_at BIGINT NOT NULL
);
CREATE INDEX attachment_references_blob
    ON attachment_references (blob_id);
CREATE UNIQUE INDEX memberships_one_owner
    ON memberships (workspace_id)
    WHERE role = 'owner';
CREATE TABLE workspace_invitations (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    email TEXT NOT NULL,
    normalized_email TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('admin', 'member')),
    delivery TEXT NOT NULL CHECK (delivery IN ('manual', 'smtp')),
    token_hash BYTEA NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    invited_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    expires_at BIGINT NOT NULL,
    accepted_at BIGINT,
    revoked_at BIGINT,
    replaced_at BIGINT,
    created_at BIGINT NOT NULL
);
CREATE UNIQUE INDEX workspace_invitations_pending_email
    ON workspace_invitations (workspace_id, normalized_email)
    WHERE accepted_at IS NULL AND revoked_at IS NULL AND replaced_at IS NULL;
CREATE INDEX workspace_invitations_workspace_created
    ON workspace_invitations (workspace_id, created_at, id);
CREATE UNIQUE INDEX workspaces_owner_membership
    ON workspaces (owner_membership_id);
CREATE FUNCTION workspaces_require_owner_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'workspace owner membership is required';
END;
$$;
CREATE TRIGGER workspaces_require_owner_insert
    BEFORE INSERT ON workspaces
    FOR EACH ROW
    WHEN (NEW.owner_membership_id IS NULL)
    EXECUTE FUNCTION workspaces_require_owner_insert_fn();
CREATE FUNCTION workspaces_require_owner_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    -- Trigger order: SQLite runs workspaces_validate_owner_update first, whose condition always
    -- holds for a NULL owner, so SQLite reports its message. Postgres runs this trigger first.
    IF NOT EXISTS (
        SELECT 1 FROM memberships
        WHERE memberships.id = NEW.owner_membership_id
          AND memberships.workspace_id = NEW.id
    ) THEN
        RAISE EXCEPTION 'workspace owner membership must belong to the workspace';
    END IF;
    RAISE EXCEPTION 'workspace owner membership is required';
    RETURN NEW;
END;
$$;
CREATE TRIGGER workspaces_require_owner_update
    BEFORE UPDATE OF owner_membership_id ON workspaces
    FOR EACH ROW
    WHEN (NEW.owner_membership_id IS NULL)
    EXECUTE FUNCTION workspaces_require_owner_update_fn();
CREATE FUNCTION workspaces_validate_owner_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM memberships
        WHERE memberships.id = NEW.owner_membership_id
          AND memberships.workspace_id = NEW.id
    )
    THEN
        RAISE EXCEPTION 'workspace owner membership must belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER workspaces_validate_owner_update
    BEFORE UPDATE OF owner_membership_id ON workspaces
    FOR EACH ROW
    EXECUTE FUNCTION workspaces_validate_owner_update_fn();
CREATE FUNCTION workspaces_apply_owner_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE memberships
    SET role = 'admin', version = version + 1, updated_at = NEW.updated_at
    WHERE id = OLD.owner_membership_id AND workspace_id = NEW.id;
    UPDATE memberships
    SET role = 'owner', version = version + 1, updated_at = NEW.updated_at
    WHERE id = NEW.owner_membership_id AND workspace_id = NEW.id;
    RETURN NULL;
END;
$$;
CREATE TRIGGER workspaces_apply_owner_update
    AFTER UPDATE OF owner_membership_id ON workspaces
    FOR EACH ROW
    WHEN (OLD.owner_membership_id != NEW.owner_membership_id)
    EXECUTE FUNCTION workspaces_apply_owner_update_fn();
CREATE FUNCTION memberships_protect_current_owner_role_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.role = 'owner' AND NEW.role != 'owner'
     AND EXISTS (
        SELECT 1 FROM workspaces
        WHERE workspaces.id = OLD.workspace_id
          AND workspaces.owner_membership_id = OLD.id
     )
    THEN
        RAISE EXCEPTION 'workspace owner role is protected';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER memberships_protect_current_owner_role
    BEFORE UPDATE OF role ON memberships
    FOR EACH ROW
    EXECUTE FUNCTION memberships_protect_current_owner_role_fn();
CREATE FUNCTION memberships_restrict_owner_role_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.role = 'owner'
     AND NOT EXISTS (
        SELECT 1 FROM workspaces
        WHERE workspaces.id = NEW.workspace_id
          AND workspaces.owner_membership_id = NEW.id
     )
    THEN
        RAISE EXCEPTION 'workspace owner role must match owner membership';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER memberships_restrict_owner_role
    BEFORE UPDATE OF role ON memberships
    FOR EACH ROW
    EXECUTE FUNCTION memberships_restrict_owner_role_fn();
CREATE TABLE maintenance_summaries (
    id TEXT PRIMARY KEY,
    kind TEXT NOT NULL,
    workspaces_purged BIGINT NOT NULL DEFAULT 0 CHECK (workspaces_purged >= 0),
    audit_events_purged BIGINT NOT NULL DEFAULT 0 CHECK (audit_events_purged >= 0),
    occurred_at BIGINT NOT NULL
, attachment_references_purged BIGINT NOT NULL DEFAULT 0
    CHECK (attachment_references_purged >= 0), attachment_blobs_purged BIGINT NOT NULL DEFAULT 0
    CHECK (attachment_blobs_purged >= 0), pending_uploads_purged BIGINT NOT NULL DEFAULT 0
    CHECK (pending_uploads_purged >= 0), files_purged BIGINT NOT NULL DEFAULT 0
    CHECK (files_purged >= 0));
CREATE INDEX maintenance_summaries_kind_time
    ON maintenance_summaries (kind, occurred_at);
CREATE FUNCTION workspaces_validate_owner_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM memberships
        WHERE memberships.id = NEW.owner_membership_id
          AND (memberships.workspace_id != NEW.id OR memberships.role != 'owner')
    )
    THEN
        RAISE EXCEPTION 'workspace owner membership must belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER workspaces_validate_owner_insert
    BEFORE INSERT ON workspaces
    FOR EACH ROW
    EXECUTE FUNCTION workspaces_validate_owner_insert_fn();
CREATE FUNCTION memberships_validate_owner_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (
        NEW.role = 'owner' AND NOT EXISTS (
            SELECT 1 FROM workspaces
            WHERE workspaces.id = NEW.workspace_id
              AND workspaces.owner_membership_id = NEW.id
        )
    ) OR EXISTS (
        SELECT 1 FROM workspaces
        WHERE workspaces.owner_membership_id = NEW.id
          AND (workspaces.id != NEW.workspace_id OR NEW.role != 'owner')
    )
    THEN
        RAISE EXCEPTION 'workspace owner role must match owner membership';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER memberships_validate_owner_insert
    BEFORE INSERT ON memberships
    FOR EACH ROW
    EXECUTE FUNCTION memberships_validate_owner_insert_fn();
CREATE TABLE attachment_file_deletions (
    id TEXT PRIMARY KEY,
    path_kind TEXT NOT NULL CHECK (path_kind IN ('blob', 'temporary')),
    path TEXT NOT NULL,
    created_at BIGINT NOT NULL,
    UNIQUE (path_kind, path)
);
CREATE TABLE security_probe_summaries (
    kind TEXT NOT NULL,
    bucket_started_at BIGINT NOT NULL,
    attempt_count BIGINT NOT NULL CHECK (attempt_count > 0),
    last_attempt_at BIGINT NOT NULL,
    PRIMARY KEY (kind, bucket_started_at)
);
CREATE TABLE labels (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    color TEXT NOT NULL,
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    UNIQUE (workspace_id, name)
);
CREATE INDEX labels_workspace_name ON labels (workspace_id, name, id);
CREATE INDEX projects_workspace_name ON projects (workspace_id, name, id);
CREATE TABLE tasks (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    status_id TEXT NOT NULL,
    title TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    priority TEXT NOT NULL DEFAULT 'none'
        CHECK (priority IN ('none', 'low', 'medium', 'high', 'urgent')),
    position BIGINT NOT NULL DEFAULT 0,
    creator_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    deleted_at BIGINT,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL
, due_at BIGINT, creator_service_account_id TEXT, due_start_at BIGINT, source_url TEXT, completed_at BIGINT, parent_task_id TEXT REFERENCES tasks(id) ON DELETE SET NULL, number BIGINT CHECK (number IS NULL OR number > 0));
CREATE INDEX tasks_workspace_position ON tasks (workspace_id, position, id);
CREATE INDEX tasks_workspace_title ON tasks (workspace_id, title, id);
CREATE INDEX tasks_workspace_created ON tasks (workspace_id, created_at, id);
CREATE INDEX tasks_workspace_updated ON tasks (workspace_id, updated_at, id);
CREATE INDEX tasks_project_status ON tasks (workspace_id, project_id, status_id, id);
CREATE INDEX tasks_workspace_deleted ON tasks (workspace_id, deleted_at, id);
CREATE TABLE task_assignees (
    task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    membership_id TEXT NOT NULL REFERENCES memberships(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    PRIMARY KEY (task_id, user_id),
    UNIQUE (task_id, membership_id)
);
CREATE INDEX task_assignees_user_task ON task_assignees (user_id, task_id);
CREATE TABLE task_labels (
    task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    label_id TEXT NOT NULL REFERENCES labels(id) ON DELETE RESTRICT,
    PRIMARY KEY (task_id, label_id)
);
CREATE INDEX task_labels_label_task ON task_labels (label_id, task_id);
CREATE TABLE task_comments (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    author_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    parent_id TEXT REFERENCES task_comments(id) ON DELETE CASCADE,
    body TEXT NOT NULL,
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL
);
CREATE INDEX task_comments_task_created ON task_comments (task_id, created_at, id);
CREATE FUNCTION tasks_validate_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    -- Trigger order: SQLite runs tasks_validate_service_account_insert before this trigger.
    IF NEW.creator_service_account_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM service_accounts
        WHERE id = NEW.creator_service_account_id
          AND workspace_id = NEW.workspace_id
    ) THEN
        RAISE EXCEPTION 'task service account must belong to the workspace';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM task_statuses
        WHERE task_statuses.id = NEW.status_id
          AND task_statuses.project_id = NEW.project_id
          AND task_statuses.workspace_id = NEW.workspace_id
    ) THEN
        RAISE EXCEPTION 'task project and status must belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER tasks_validate_scope_insert
    BEFORE INSERT ON tasks
    FOR EACH ROW
    EXECUTE FUNCTION tasks_validate_scope_insert_fn();
CREATE FUNCTION tasks_validate_scope_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    -- Trigger order: SQLite runs tasks_workspace_immutable before this trigger.
    IF NEW.workspace_id <> OLD.workspace_id THEN
        RAISE EXCEPTION 'task workspace is immutable';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM task_statuses
        WHERE task_statuses.id = NEW.status_id
          AND task_statuses.project_id = NEW.project_id
          AND task_statuses.workspace_id = NEW.workspace_id
    ) THEN
        RAISE EXCEPTION 'task project and status must belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER tasks_validate_scope_update
    BEFORE UPDATE OF workspace_id, project_id, status_id ON tasks
    FOR EACH ROW
    EXECUTE FUNCTION tasks_validate_scope_update_fn();
CREATE FUNCTION task_assignees_validate_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tasks JOIN memberships
          ON memberships.id = NEW.membership_id
         AND memberships.workspace_id = tasks.workspace_id
         AND memberships.user_id = NEW.user_id
        JOIN users ON users.id = memberships.user_id AND users.suspended_at IS NULL
        WHERE tasks.id = NEW.task_id
    )
    THEN
        RAISE EXCEPTION 'task assignee must be an active workspace membership';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER task_assignees_validate_scope_insert
    BEFORE INSERT ON task_assignees
    FOR EACH ROW
    EXECUTE FUNCTION task_assignees_validate_scope_insert_fn();
CREATE FUNCTION task_assignees_validate_scope_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tasks JOIN memberships
          ON memberships.id = NEW.membership_id
         AND memberships.workspace_id = tasks.workspace_id
         AND memberships.user_id = NEW.user_id
        JOIN users ON users.id = memberships.user_id AND users.suspended_at IS NULL
        WHERE tasks.id = NEW.task_id
    )
    THEN
        RAISE EXCEPTION 'task assignee must be an active workspace membership';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER task_assignees_validate_scope_update
    BEFORE UPDATE OF task_id, membership_id, user_id ON task_assignees
    FOR EACH ROW
    EXECUTE FUNCTION task_assignees_validate_scope_update_fn();
CREATE FUNCTION task_labels_validate_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tasks JOIN labels ON labels.id = NEW.label_id
        WHERE tasks.id = NEW.task_id AND labels.workspace_id = tasks.workspace_id
    )
    THEN
        RAISE EXCEPTION 'task label must belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER task_labels_validate_scope_insert
    BEFORE INSERT ON task_labels
    FOR EACH ROW
    EXECUTE FUNCTION task_labels_validate_scope_insert_fn();
CREATE FUNCTION task_labels_validate_scope_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tasks JOIN labels ON labels.id = NEW.label_id
        WHERE tasks.id = NEW.task_id AND labels.workspace_id = tasks.workspace_id
    )
    THEN
        RAISE EXCEPTION 'task label must belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER task_labels_validate_scope_update
    BEFORE UPDATE OF task_id, label_id ON task_labels
    FOR EACH ROW
    EXECUTE FUNCTION task_labels_validate_scope_update_fn();
CREATE FUNCTION task_comments_validate_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tasks
        WHERE tasks.id = NEW.task_id AND tasks.workspace_id = NEW.workspace_id
    ) OR (
        NEW.parent_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM task_comments
            WHERE task_comments.id = NEW.parent_id
              AND task_comments.task_id = NEW.task_id
              AND task_comments.workspace_id = NEW.workspace_id
        )
    )
    THEN
        RAISE EXCEPTION 'task comment must belong to its task and workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER task_comments_validate_scope_insert
    BEFORE INSERT ON task_comments
    FOR EACH ROW
    EXECUTE FUNCTION task_comments_validate_scope_insert_fn();
CREATE FUNCTION task_comments_validate_scope_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tasks
        WHERE tasks.id = NEW.task_id AND tasks.workspace_id = NEW.workspace_id
    ) OR (
        NEW.parent_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM task_comments
            WHERE task_comments.id = NEW.parent_id
              AND task_comments.task_id = NEW.task_id
              AND task_comments.workspace_id = NEW.workspace_id
        )
    )
    THEN
        RAISE EXCEPTION 'task comment must belong to its task and workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER task_comments_validate_scope_update
    BEFORE UPDATE OF workspace_id, task_id, parent_id ON task_comments
    FOR EACH ROW
    EXECUTE FUNCTION task_comments_validate_scope_update_fn();
