    EXECUTE FUNCTION attachment_blobs_workspace_immutable_fn();
CREATE FUNCTION attachment_references_reject_scope_mismatch_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM attachment_blobs
        WHERE attachment_blobs.id = NEW.blob_id
          AND attachment_blobs.workspace_id <> NEW.workspace_id
    ) OR EXISTS (
        SELECT 1 FROM tasks
        WHERE tasks.id = NEW.task_id
          AND tasks.workspace_id <> NEW.workspace_id
    ) OR (
        NEW.comment_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM task_comments
            WHERE task_comments.id = NEW.comment_id
              AND (
                task_comments.task_id <> NEW.task_id
                OR task_comments.workspace_id <> NEW.workspace_id
              )
        )
    )
    THEN
        RAISE EXCEPTION 'attachment reference scope mismatch';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER attachment_references_reject_scope_mismatch
    BEFORE INSERT ON attachment_references
    FOR EACH ROW
    EXECUTE FUNCTION attachment_references_reject_scope_mismatch_fn();
CREATE FUNCTION attachment_references_scope_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'attachment reference scope is immutable';
END;
$$;
CREATE TRIGGER attachment_references_scope_immutable
    BEFORE UPDATE OF workspace_id, task_id, comment_id, blob_id ON attachment_references
    FOR EACH ROW
    WHEN (NEW.workspace_id <> OLD.workspace_id
      OR NEW.task_id <> OLD.task_id
      OR NEW.comment_id IS DISTINCT FROM OLD.comment_id
      OR NEW.blob_id <> OLD.blob_id)
    EXECUTE FUNCTION attachment_references_scope_immutable_fn();
CREATE FUNCTION task_comments_cleanup_attachments_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE attachment_blobs
    SET quarantine_until = GREATEST(
        quarantine_until,
        floor(EXTRACT(EPOCH FROM clock_timestamp()))::BIGINT * 1000 + 86400000
    )
    WHERE id IN (
        SELECT blob_id FROM attachment_references WHERE comment_id = OLD.id
    );
    DELETE FROM attachment_references WHERE comment_id = OLD.id;
    RETURN OLD;
END;
$$;
CREATE TRIGGER task_comments_cleanup_attachments
    BEFORE DELETE ON task_comments
    FOR EACH ROW
    EXECUTE FUNCTION task_comments_cleanup_attachments_fn();
CREATE FUNCTION tasks_cleanup_attachments_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE attachment_blobs
    SET quarantine_until = GREATEST(
        quarantine_until,
        floor(EXTRACT(EPOCH FROM clock_timestamp()))::BIGINT * 1000 + 86400000
    )
    WHERE id IN (
        SELECT blob_id FROM attachment_references WHERE task_id = OLD.id
    );
    DELETE FROM attachment_references WHERE task_id = OLD.id;
    RETURN OLD;
END;
$$;
CREATE TRIGGER tasks_cleanup_attachments
    BEFORE DELETE ON tasks
    FOR EACH ROW
    EXECUTE FUNCTION tasks_cleanup_attachments_fn();
