CREATE TABLE realtime_sequences (
    workspace_id TEXT PRIMARY KEY,
    sequence BIGINT NOT NULL
);
CREATE FUNCTION audit_workspace_realtime_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO realtime_sequences (workspace_id, sequence) VALUES (NEW.workspace_id, 1)
    ON CONFLICT (workspace_id) DO UPDATE SET sequence = realtime_sequences.sequence + 1;
    INSERT INTO outbox_events (id, scope, sequence, workspace_id, topic, payload_json, created_at)
    SELECT NEW.id, NEW.workspace_id, sequence, NEW.workspace_id, 'workspace.changed', '{}', NEW.occurred_at
    FROM realtime_sequences WHERE workspace_id = NEW.workspace_id;
    RETURN NULL;
END;
$$;
CREATE TRIGGER audit_workspace_realtime
    AFTER INSERT ON audit_events
    FOR EACH ROW
    WHEN (NEW.workspace_id IS NOT NULL AND NEW.outcome = 'success')
    EXECUTE FUNCTION audit_workspace_realtime_fn();
CREATE INDEX outbox_events_workspace_created ON outbox_events (workspace_id, created_at);
CREATE TABLE api_tokens (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    token_hash BYTEA NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    token_prefix TEXT NOT NULL,
    can_read BIGINT NOT NULL CHECK (can_read IN (0, 1)),
    can_write BIGINT NOT NULL CHECK (can_write IN (0, 1)),
    created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    created_at BIGINT NOT NULL,
    last_used_at BIGINT,
    revoked_at BIGINT
, project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT, service_account_id TEXT, expires_at BIGINT);
CREATE INDEX api_tokens_workspace_created ON api_tokens (workspace_id, created_at DESC);
CREATE FUNCTION api_tokens_validate_project_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    -- Trigger order: SQLite runs api_tokens_validate_service_account_insert before this trigger.
    IF NEW.service_account_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM service_accounts
        WHERE id = NEW.service_account_id
          AND workspace_id = NEW.workspace_id
          AND disabled_at IS NULL
    ) THEN
        RAISE EXCEPTION 'api token service account must be active and belong to the workspace';
    END IF;
    IF NEW.project_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM projects
        WHERE projects.id = NEW.project_id
          AND projects.workspace_id = NEW.workspace_id
          AND projects.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'api token project must be active and belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER api_tokens_validate_project_insert
    BEFORE INSERT ON api_tokens
    FOR EACH ROW
    EXECUTE FUNCTION api_tokens_validate_project_insert_fn();
CREATE FUNCTION api_tokens_validate_project_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.project_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM projects
        WHERE projects.id = NEW.project_id
          AND projects.workspace_id = NEW.workspace_id
          AND projects.deleted_at IS NULL
    )
    THEN
        RAISE EXCEPTION 'api token project must be active and belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER api_tokens_validate_project_update
    BEFORE UPDATE OF workspace_id, project_id ON api_tokens
    FOR EACH ROW
    EXECUTE FUNCTION api_tokens_validate_project_update_fn();
