CREATE TABLE task_relations (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    related_task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    type TEXT NOT NULL CHECK (type IN ('blocks', 'related', 'duplicate')),
    previous_status_id TEXT REFERENCES task_statuses(id) ON DELETE SET NULL,
    created_by TEXT REFERENCES users(id) ON DELETE SET NULL,
    created_at BIGINT NOT NULL,
    CHECK (task_id <> related_task_id),
    CHECK (type = 'duplicate' OR previous_status_id IS NULL),
    CHECK (type <> 'related' OR task_id < related_task_id COLLATE "C")
);
CREATE UNIQUE INDEX task_relations_pair
    ON task_relations (LEAST(task_id COLLATE "C", related_task_id COLLATE "C"),
     GREATEST(task_id COLLATE "C", related_task_id COLLATE "C"));
CREATE UNIQUE INDEX task_relations_one_duplicate
    ON task_relations (task_id) WHERE type = 'duplicate';
CREATE INDEX task_relations_task ON task_relations (task_id, type);
CREATE INDEX task_relations_related ON task_relations (related_task_id, type);
CREATE FUNCTION task_relations_validate_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tasks WHERE tasks.id = NEW.task_id AND tasks.workspace_id = NEW.workspace_id
    ) OR NOT EXISTS (
        SELECT 1 FROM tasks WHERE tasks.id = NEW.related_task_id AND tasks.workspace_id = NEW.workspace_id
    )
    THEN
        RAISE EXCEPTION 'task relation tasks must belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER task_relations_validate_scope_insert
    BEFORE INSERT ON task_relations
    FOR EACH ROW
    EXECUTE FUNCTION task_relations_validate_scope_insert_fn();
CREATE FUNCTION task_relations_validate_scope_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tasks WHERE tasks.id = NEW.task_id AND tasks.workspace_id = NEW.workspace_id
    ) OR NOT EXISTS (
        SELECT 1 FROM tasks WHERE tasks.id = NEW.related_task_id AND tasks.workspace_id = NEW.workspace_id
    )
    THEN
        RAISE EXCEPTION 'task relation tasks must belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER task_relations_validate_scope_update
    BEFORE UPDATE OF workspace_id, task_id, related_task_id ON task_relations
    FOR EACH ROW
    EXECUTE FUNCTION task_relations_validate_scope_update_fn();
CREATE FUNCTION task_relations_duplicate_chain_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.type = 'duplicate' AND (
        EXISTS (SELECT 1 FROM task_relations
                WHERE task_relations.task_id = NEW.related_task_id AND task_relations.type = 'duplicate')
        OR EXISTS (SELECT 1 FROM task_relations
                   WHERE task_relations.related_task_id = NEW.task_id AND task_relations.type = 'duplicate')
    )
    THEN
        RAISE EXCEPTION 'duplicate relations cannot chain';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER task_relations_duplicate_chain_insert
    BEFORE INSERT ON task_relations
    FOR EACH ROW
    EXECUTE FUNCTION task_relations_duplicate_chain_insert_fn();
CREATE FUNCTION task_relations_duplicate_chain_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.type = 'duplicate' AND (
        EXISTS (SELECT 1 FROM task_relations
                WHERE task_relations.id <> NEW.id
                  AND task_relations.task_id = NEW.related_task_id AND task_relations.type = 'duplicate')
        OR EXISTS (SELECT 1 FROM task_relations
                   WHERE task_relations.id <> NEW.id
                     AND task_relations.related_task_id = NEW.task_id AND task_relations.type = 'duplicate')
    )
    THEN
        RAISE EXCEPTION 'duplicate relations cannot chain';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER task_relations_duplicate_chain_update
    BEFORE UPDATE OF task_id, related_task_id, type ON task_relations
    FOR EACH ROW
    EXECUTE FUNCTION task_relations_duplicate_chain_update_fn();
CREATE TABLE pages (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    parent_id TEXT REFERENCES pages(id) ON DELETE SET NULL,
    title TEXT NOT NULL DEFAULT '',
    icon TEXT,
    cover_url TEXT,
    cover_position TEXT,
    content_json TEXT NOT NULL DEFAULT '[]',
    content_text TEXT NOT NULL DEFAULT '',
    position BIGINT NOT NULL DEFAULT 0,
    creator_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    updated_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    deleted_at BIGINT,
    -- The page whose DELETE trashed this row; restore brings back exactly that batch.
    trashed_with TEXT
, teamspace_id TEXT, owner_id TEXT REFERENCES users(id) ON DELETE CASCADE, full_width BIGINT NOT NULL DEFAULT 0 CHECK (full_width IN (0, 1)), locked_at BIGINT, locked_by TEXT REFERENCES users(id) ON DELETE SET NULL
