CREATE FUNCTION pages_space_exactly_one_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    -- Trigger order: SQLite runs pages_teamspace_scope_insert before this trigger.
    IF NEW.teamspace_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM teamspaces
        WHERE teamspaces.id = NEW.teamspace_id AND teamspaces.workspace_id = NEW.workspace_id
    ) THEN
        RAISE EXCEPTION 'page teamspace must belong to the workspace';
    END IF;
    RAISE EXCEPTION 'page must belong to exactly one space';
    RETURN NEW;
END;
$$;
