        WHERE teamspaces.id = NEW.teamspace_id AND teamspaces.workspace_id = NEW.workspace_id
    ) THEN
        RAISE EXCEPTION 'page teamspace must belong to the workspace';
    END IF;
    RAISE EXCEPTION 'page must belong to exactly one space';
