CREATE FUNCTION pages_parent_space_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.parent_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pages AS parent
        WHERE parent.id = NEW.parent_id
          AND parent.teamspace_id IS NOT DISTINCT FROM NEW.teamspace_id
          AND parent.owner_id IS NOT DISTINCT FROM NEW.owner_id
    )
    THEN
        RAISE EXCEPTION 'page must share its parent''s space';
    END IF;
    RETURN NEW;
END;
$$;
