    WHEN (NEW.workspace_id <> OLD.workspace_id OR NEW.page_id <> OLD.page_id
        OR NEW.blob_id <> OLD.blob_id)
    EXECUTE FUNCTION page_files_scope_immutable_fn();
CREATE FUNCTION page_files_quarantine_blob_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE attachment_blobs
    SET quarantine_until = GREATEST(
        quarantine_until,
        floor(EXTRACT(EPOCH FROM clock_timestamp()))::BIGINT * 1000 + 86400000
    )
    WHERE id = OLD.blob_id;
    RETURN NULL;
END;
$$;
CREATE TRIGGER page_files_quarantine_blob
    AFTER DELETE ON page_files
    FOR EACH ROW
    EXECUTE FUNCTION page_files_quarantine_blob_fn();
CREATE TABLE notion_imports (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    status TEXT NOT NULL CHECK (status IN (
        'scanning', 'ready', 'queued', 'importing', 'completed', 'failed', 'cancelled', 'expired'
    )),
    token_ciphertext BYTEA,
    notion_workspace_name TEXT,
    tree_json TEXT,
    selection_json TEXT,
    target_teamspace_id TEXT REFERENCES teamspaces(id) ON DELETE SET NULL,
    target_private BIGINT NOT NULL DEFAULT 0 CHECK (target_private IN (0, 1)),
    target_parent_page_id TEXT REFERENCES pages(id) ON DELETE SET NULL,
    total BIGINT NOT NULL DEFAULT 0 CHECK (total >= 0),
    done BIGINT NOT NULL DEFAULT 0 CHECK (done >= 0),
    failed BIGINT NOT NULL DEFAULT 0 CHECK (failed >= 0),
    report_json TEXT,
    error TEXT,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    CHECK (token_ciphertext IS NULL OR status IN ('scanning', 'ready', 'queued', 'importing')),
    CHECK (target_private = 0 OR target_teamspace_id IS NULL)
);
CREATE INDEX notion_imports_user ON notion_imports (user_id, workspace_id, created_at);
CREATE INDEX notion_imports_workspace ON notion_imports (workspace_id);
