CREATE TABLE page_search_rows (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    page_id TEXT NOT NULL UNIQUE
);
-- SQLite: CREATE VIRTUAL TABLE page_search USING fts5(title, body,
--     tokenize = 'unicode61 remove_diacritics 2'), keyed by rowid = page_search_rows.id.
-- Title lexemes have weight A and body lexemes weight B, so ts_rank(..., '{0, 0, 0.1, 1}')
-- weights titles 10x like bm25(page_search, 10.0, 1.0).
CREATE TABLE page_search (
    rowid BIGINT PRIMARY KEY,
    title TEXT,
    body TEXT,
    search_vector tsvector GENERATED ALWAYS AS (
        setweight(to_tsvector('orbit_search', regexp_replace(coalesce(title, ''), '[^[:alnum:]]+', ' ', 'g')), 'A')
        || setweight(to_tsvector('orbit_search', regexp_replace(coalesce(body, ''), '[^[:alnum:]]+', ' ', 'g')), 'B')
    ) STORED
);
CREATE INDEX page_search_search_vector ON page_search USING GIN (search_vector);
CREATE FUNCTION page_search_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO page_search_rows (page_id) VALUES (NEW.id);
    INSERT INTO page_search (rowid, title, body)
    VALUES (
        (SELECT id FROM page_search_rows WHERE page_id = NEW.id),
        replace(replace(NEW.title, chr(2), ''), chr(3), ''),
        replace(replace(NEW.content_text, chr(2), ''), chr(3), '')
    );
    RETURN NULL;
END;
$$;
CREATE TRIGGER page_search_insert
    AFTER INSERT ON pages
    FOR EACH ROW
    EXECUTE FUNCTION page_search_insert_fn();
CREATE FUNCTION page_search_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE page_search
    SET title = replace(replace(NEW.title, chr(2), ''), chr(3), ''),
        body = replace(replace(NEW.content_text, chr(2), ''), chr(3), '')
    WHERE rowid = (SELECT id FROM page_search_rows WHERE page_id = NEW.id);
    RETURN NULL;
END;
$$;
CREATE TRIGGER page_search_update
    AFTER UPDATE OF title, content_text ON pages
    FOR EACH ROW
    WHEN (NEW.title IS DISTINCT FROM OLD.title OR NEW.content_text IS DISTINCT FROM OLD.content_text)
    EXECUTE FUNCTION page_search_update_fn();
CREATE FUNCTION page_search_delete_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM page_search
    WHERE rowid = (SELECT id FROM page_search_rows WHERE page_id = OLD.id);
    DELETE FROM page_search_rows WHERE page_id = OLD.id;
    RETURN NULL;
END;
$$;
CREATE TRIGGER page_search_delete
    AFTER DELETE ON pages
    FOR EACH ROW
    EXECUTE FUNCTION page_search_delete_fn();
