    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (id = 1),
    generation TEXT NOT NULL CHECK (length(generation) BETWEEN 1 AND 64)
);
CREATE FUNCTION page_collab_docs_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
