CREATE TABLE page_threads (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    page_id TEXT NOT NULL REFERENCES pages(id) ON DELETE CASCADE,
    created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    -- The selected text when the thread was started (shown in the Comments panel).
    quote TEXT NOT NULL DEFAULT '' CHECK (length(quote) <= 1000),
    resolved_at BIGINT,
    resolved_by TEXT REFERENCES users(id) ON DELETE SET NULL,
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    CHECK ((resolved_at IS NULL) OR (resolved_at >= created_at))
);
CREATE INDEX page_threads_page_created ON page_threads (page_id, created_at, id);
CREATE INDEX page_threads_workspace ON page_threads (workspace_id);
CREATE INDEX page_threads_created_by ON page_threads (created_by);
CREATE INDEX page_threads_resolved_by ON page_threads (resolved_by);
CREATE FUNCTION page_threads_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pages WHERE pages.id = NEW.page_id AND pages.workspace_id = NEW.workspace_id
    )
    THEN
        RAISE EXCEPTION 'thread page must belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER page_threads_scope_insert
    BEFORE INSERT ON page_threads
    FOR EACH ROW
    EXECUTE FUNCTION page_threads_scope_insert_fn();
CREATE FUNCTION page_threads_scope_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'thread scope is immutable';
END;
$$;
CREATE TRIGGER page_threads_scope_immutable
    BEFORE UPDATE OF workspace_id, page_id ON page_threads
    FOR EACH ROW
    WHEN (NEW.workspace_id <> OLD.workspace_id OR NEW.page_id <> OLD.page_id)
    EXECUTE FUNCTION page_threads_scope_immutable_fn();
CREATE TABLE page_comments (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    page_id TEXT NOT NULL REFERENCES pages(id) ON DELETE CASCADE,
    thread_id TEXT NOT NULL REFERENCES page_threads(id) ON DELETE CASCADE,
    author_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    -- BlockNote blocks of the comment editor (paragraphs, styled text, mentions); '[]' once deleted.
    body_json TEXT NOT NULL DEFAULT '[]',
    body_text TEXT NOT NULL DEFAULT '',
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    edited_at BIGINT,
    deleted_at BIGINT
);
CREATE INDEX page_comments_thread_created ON page_comments (thread_id, created_at, id);
CREATE INDEX page_comments_page ON page_comments (page_id);
CREATE INDEX page_comments_workspace ON page_comments (workspace_id);
CREATE INDEX page_comments_author ON page_comments (author_id);
CREATE FUNCTION page_comments_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM page_threads
        WHERE page_threads.id = NEW.thread_id
          AND page_threads.page_id = NEW.page_id
          AND page_threads.workspace_id = NEW.workspace_id
    )
    THEN
        RAISE EXCEPTION 'comment must belong to the page thread';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER page_comments_scope_insert
    BEFORE INSERT ON page_comments
    FOR EACH ROW
    EXECUTE FUNCTION page_comments_scope_insert_fn();
CREATE FUNCTION page_comments_scope_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'comment scope is immutable';
END;
$$;
CREATE TRIGGER page_comments_scope_immutable
    BEFORE UPDATE OF workspace_id, page_id, thread_id, author_id ON page_comments
    FOR EACH ROW
    WHEN (NEW.workspace_id <> OLD.workspace_id OR NEW.page_id <> OLD.page_id
        OR NEW.thread_id <> OLD.thread_id OR NEW.author_id <> OLD.author_id)
    EXECUTE FUNCTION page_comments_scope_immutable_fn();
CREATE TABLE page_comment_mentions (
    comment_id TEXT NOT NULL REFERENCES page_comments(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    PRIMARY KEY (comment_id, user_id)
);
CREATE INDEX page_comment_mentions_user ON page_comment_mentions (user_id);
CREATE INDEX pages_locked_by ON pages (locked_by) WHERE locked_by IS NOT NULL;
CREATE TABLE page_visits (
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    page_id TEXT NOT NULL REFERENCES pages(id) ON DELETE CASCADE,
    visited_at BIGINT NOT NULL,
    PRIMARY KEY (user_id, page_id)
);
CREATE INDEX page_visits_workspace_user_recent
    ON page_visits (workspace_id, user_id, visited_at DESC, page_id);
CREATE INDEX page_visits_page ON page_visits (page_id);
CREATE FUNCTION page_visits_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pages WHERE pages.id = NEW.page_id AND pages.workspace_id = NEW.workspace_id
    )
    THEN
        RAISE EXCEPTION 'visited page must belong to the workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER page_visits_scope_insert
    BEFORE INSERT ON page_visits
    FOR EACH ROW
    EXECUTE FUNCTION page_visits_scope_insert_fn();
CREATE FUNCTION page_visits_identity_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'page visit identity is immutable';
END;
$$;
CREATE TRIGGER page_visits_identity_immutable
    BEFORE UPDATE OF workspace_id, user_id, page_id ON page_visits
    FOR EACH ROW
    WHEN (NEW.workspace_id <> OLD.workspace_id OR NEW.user_id <> OLD.user_id
        OR NEW.page_id <> OLD.page_id)
    EXECUTE FUNCTION page_visits_identity_immutable_fn();
CREATE TABLE saved_views (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    owner_user_id TEXT NOT NULL REFERENCES users(id),
    name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 80),
    description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 500),
    icon TEXT,
    color TEXT,
    visibility TEXT NOT NULL CHECK (visibility IN ('personal', 'workspace')),
    state_json TEXT NOT NULL,
    version BIGINT NOT NULL DEFAULT 1,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL
);
CREATE INDEX saved_views_workspace_visibility ON saved_views (workspace_id, visibility);
CREATE INDEX saved_views_workspace_owner ON saved_views (workspace_id, owner_user_id);
CREATE TABLE saved_view_favorites (
    view_id TEXT NOT NULL REFERENCES saved_views(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id),
    position BIGINT NOT NULL,
    created_at BIGINT NOT NULL,
    PRIMARY KEY (view_id, user_id)
);
CREATE INDEX saved_view_favorites_user ON saved_view_favorites (user_id, position);
CREATE TABLE view_preferences (
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id),
    page_key TEXT NOT NULL,
    state_json TEXT NOT NULL,
    updated_at BIGINT NOT NULL,
    PRIMARY KEY (workspace_id, user_id, page_key)
);
CREATE INDEX tasks_workspace_completed ON tasks (workspace_id, completed_at, id);
CREATE FUNCTION tasks_completed_at_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.completed_at IS NULL AND EXISTS (
        SELECT 1 FROM task_statuses
        WHERE task_statuses.id = NEW.status_id
          AND task_statuses.category IN ('completed', 'cancelled', 'duplicate')
    ) THEN
        UPDATE tasks SET completed_at = NEW.updated_at WHERE id = NEW.id;
    END IF;
    RETURN NULL;
END;
$$;
CREATE TRIGGER tasks_completed_at_insert
    AFTER INSERT ON tasks
    FOR EACH ROW
    EXECUTE FUNCTION tasks_completed_at_insert_fn();
CREATE FUNCTION tasks_completed_at_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM task_statuses
        WHERE task_statuses.id = NEW.status_id
          AND task_statuses.category IN ('completed', 'cancelled', 'duplicate')
    ) <> EXISTS (
        SELECT 1 FROM task_statuses
        WHERE task_statuses.id = OLD.status_id
          AND task_statuses.category IN ('completed', 'cancelled', 'duplicate')
    ) THEN
        UPDATE tasks
        SET completed_at = CASE
            WHEN EXISTS (
                SELECT 1 FROM task_statuses
                WHERE task_statuses.id = NEW.status_id
                  AND task_statuses.category IN ('completed', 'cancelled', 'duplicate')
            ) THEN NEW.updated_at
            ELSE NULL
        END
        WHERE id = NEW.id;
    END IF;
    RETURN NULL;
END;
$$;
CREATE TRIGGER tasks_completed_at_update
    AFTER UPDATE OF status_id ON tasks
    FOR EACH ROW
    EXECUTE FUNCTION tasks_completed_at_update_fn();
CREATE INDEX tasks_parent_idx ON tasks (parent_task_id) WHERE parent_task_id IS NOT NULL;
CREATE FUNCTION tasks_parent_validate_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.parent_task_id IS NOT NULL AND (
        NEW.parent_task_id = NEW.id
        OR NOT EXISTS (
            SELECT 1 FROM tasks AS parent
            WHERE parent.id = NEW.parent_task_id AND parent.workspace_id = NEW.workspace_id
        )
    )
    THEN
        RAISE EXCEPTION 'task parent must be another task in the same workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER tasks_parent_validate_insert
    BEFORE INSERT ON tasks
    FOR EACH ROW
    EXECUTE FUNCTION tasks_parent_validate_insert_fn();
CREATE FUNCTION tasks_parent_validate_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.parent_task_id IS NOT NULL AND (
        NEW.parent_task_id = NEW.id
        OR NOT EXISTS (
            SELECT 1 FROM tasks AS parent
            WHERE parent.id = NEW.parent_task_id AND parent.workspace_id = NEW.workspace_id
        )
    )
    THEN
        RAISE EXCEPTION 'task parent must be another task in the same workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER tasks_parent_validate_update
    BEFORE UPDATE OF parent_task_id ON tasks
    FOR EACH ROW
    EXECUTE FUNCTION tasks_parent_validate_update_fn();
CREATE TABLE oauth_clients (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    redirect_uris TEXT NOT NULL CHECK (orbit_json_valid(redirect_uris)),
    created_at BIGINT NOT NULL
);
CREATE TABLE oauth_grants (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL REFERENCES oauth_clients(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    project_ids TEXT NOT NULL CHECK (orbit_json_valid(project_ids)),
    resource TEXT NOT NULL,
    scope TEXT NOT NULL CHECK (scope = 'tasks:read'),
    revoked_at BIGINT,
    created_at BIGINT NOT NULL
);
CREATE INDEX oauth_grants_user ON oauth_grants(user_id, created_at);
CREATE TABLE oauth_requests (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL REFERENCES oauth_clients(id) ON DELETE CASCADE,
    redirect_uri TEXT NOT NULL,
    state TEXT,
    pkce TEXT NOT NULL,
    resource TEXT NOT NULL,
    user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
    csrf_hash BYTEA CHECK (csrf_hash IS NULL OR octet_length(csrf_hash) = 32),
    expires_at BIGINT NOT NULL,
    code_hash BYTEA UNIQUE CHECK (code_hash IS NULL OR octet_length(code_hash) = 32),
    grant_id TEXT REFERENCES oauth_grants(id) ON DELETE CASCADE,
    used_at BIGINT
);
CREATE INDEX oauth_requests_expiry ON oauth_requests(expires_at);
CREATE TABLE oauth_tokens (
    access_hash BYTEA PRIMARY KEY CHECK (octet_length(access_hash) = 32),
    refresh_hash BYTEA NOT NULL UNIQUE CHECK (octet_length(refresh_hash) = 32),
    grant_id TEXT NOT NULL REFERENCES oauth_grants(id) ON DELETE CASCADE,
    access_expires_at BIGINT NOT NULL,
    refresh_expires_at BIGINT NOT NULL,
    refresh_used_at BIGINT
);
CREATE INDEX oauth_tokens_grant ON oauth_tokens(grant_id);
CREATE TABLE user_shortcuts (
    user_id TEXT PRIMARY KEY REFERENCES users(id),
    bindings_json TEXT NOT NULL CHECK (orbit_json_valid(bindings_json)),
    updated_at BIGINT NOT NULL
);
CREATE TABLE chat_categories (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 80),
    position BIGINT NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL
);
CREATE INDEX chat_categories_workspace ON chat_categories (workspace_id, position);
CREATE TABLE chat_conversations (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    kind TEXT NOT NULL CHECK (kind IN ('public', 'private', 'dm')),
    -- Normalized by the server (lower case, `-` for spaces); empty for a DM.
    name TEXT NOT NULL DEFAULT '' CHECK (length(name) <= 80),
    topic TEXT NOT NULL DEFAULT '' CHECK (length(topic) <= 250),
    category_id TEXT REFERENCES chat_categories(id) ON DELETE SET NULL,
    -- Order inside its category.
    position BIGINT NOT NULL DEFAULT 0,
    -- `#general`: every workspace member is in it; it cannot be left, archived or made private.
    is_default BIGINT NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),
    -- The sorted member ids of a DM joined by `,`, so one set of people has one DM.
    dm_key TEXT,
    archived_at BIGINT,
    created_by TEXT NOT NULL REFERENCES users(id),
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    last_message_at BIGINT,
    -- Live main-list rows of kind 'message'. A member's unread count is this minus `read_count`.
    message_count BIGINT NOT NULL DEFAULT 0 CHECK (message_count >= 0),
    CHECK ((kind = 'dm') = (dm_key IS NOT NULL)),
    CHECK (kind = 'dm' OR length(name) >= 1),
    CHECK (is_default = 0 OR (kind = 'public' AND archived_at IS NULL))
);
CREATE INDEX chat_conversations_workspace ON chat_conversations (workspace_id, kind);
CREATE INDEX chat_conversations_category ON chat_conversations (category_id);
CREATE UNIQUE INDEX chat_conversations_dm ON chat_conversations (workspace_id, dm_key)
    WHERE dm_key IS NOT NULL;
CREATE UNIQUE INDEX chat_conversations_name ON chat_conversations (workspace_id, name)
    WHERE kind <> 'dm' AND archived_at IS NULL;
CREATE UNIQUE INDEX chat_conversations_default ON chat_conversations (workspace_id)
    WHERE is_default = 1;
CREATE TABLE chat_members (
    conversation_id TEXT NOT NULL REFERENCES chat_conversations(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL,
    workspace_id TEXT NOT NULL,
    notify TEXT NOT NULL CHECK (notify IN ('all', 'mentions', 'muted')),
    favorite BIGINT NOT NULL DEFAULT 0 CHECK (favorite IN (0, 1)),
    -- A position, not a reference: the message it names may be deleted later.
    last_read_message_id TEXT,
    -- How many of the conversation's `message_count` rows are not unread for this member.
    read_count BIGINT NOT NULL DEFAULT 0 CHECK (read_count >= 0),
    -- Unread messages that mention this member (`@user`).
    mention_count BIGINT NOT NULL DEFAULT 0 CHECK (mention_count >= 0),
    -- Unread messages with `@channel` or `@here`. Not shown while the conversation is muted.
    broadcast_count BIGINT NOT NULL DEFAULT 0 CHECK (broadcast_count >= 0),
    joined_at BIGINT NOT NULL,
    PRIMARY KEY (conversation_id, user_id),
    FOREIGN KEY (workspace_id, user_id) REFERENCES memberships(workspace_id, user_id) ON DELETE CASCADE
);
CREATE INDEX chat_members_user ON chat_members (workspace_id, user_id);
CREATE FUNCTION chat_members_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM chat_conversations
        WHERE chat_conversations.id = NEW.conversation_id
          AND chat_conversations.workspace_id = NEW.workspace_id
    )
    THEN
        RAISE EXCEPTION 'chat member must belong to the conversation''s workspace';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER chat_members_scope_insert
    BEFORE INSERT ON chat_members
    FOR EACH ROW
    EXECUTE FUNCTION chat_members_scope_insert_fn();
CREATE TABLE chat_messages (
    -- Stable through VACUUM INTO (backups); the search index refers to it.
    row_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- UUIDv7 made by the server; every list and cursor orders by it.
    id TEXT NOT NULL UNIQUE,
    conversation_id TEXT NOT NULL REFERENCES chat_conversations(id) ON DELETE CASCADE,
    -- Set on a thread reply. A root is never hard-deleted while it has replies.
    thread_root_id TEXT REFERENCES chat_messages(id) ON DELETE CASCADE,
    -- 'pin', 'join' and 'leave' are one-line system rows about `author_id`.
    kind TEXT NOT NULL CHECK (kind IN ('message', 'pin', 'join', 'leave')),
    author_id TEXT NOT NULL REFERENCES users(id),
    -- Markdown source with mention tokens (`<@id>`, `<#id>`, `<!channel>`, `<!here>`).
    body TEXT NOT NULL CHECK (length(body) <= 4000),
    mention_channel BIGINT NOT NULL DEFAULT 0 CHECK (mention_channel IN (0, 1)),
    mention_here BIGINT NOT NULL DEFAULT 0 CHECK (mention_here IN (0, 1)),
    -- A thread reply that also shows in the conversation's main list.
    also_in_channel BIGINT NOT NULL DEFAULT 0 CHECK (also_in_channel IN (0, 1)),
    -- Made by the sender; a send that is tried again finds its first message by it.
    nonce TEXT CHECK (nonce IS NULL OR length(nonce) BETWEEN 1 AND 64),
    pinned_at BIGINT,
    pinned_by TEXT REFERENCES users(id),
    edited_at BIGINT,
    -- Only on a root that still has replies; every other deleted message is removed.
    deleted_at BIGINT,
    created_at BIGINT NOT NULL,
    -- Thread summary, on a root only.
    reply_count BIGINT NOT NULL DEFAULT 0 CHECK (reply_count >= 0),
    last_reply_id TEXT,
    -- The first reply authors, for the avatars of the summary row.
    reply_user_ids TEXT NOT NULL DEFAULT '[]' CHECK (orbit_json_valid(reply_user_ids)), reply_to_id TEXT, forward_of_id TEXT, forward_conversation_id TEXT, forward_author_id TEXT, forward_created_at BIGINT, sticker_id TEXT,
    CHECK (also_in_channel = 0 OR thread_root_id IS NOT NULL),
    CHECK ((pinned_at IS NULL) = (pinned_by IS NULL))
);
CREATE INDEX chat_messages_conversation ON chat_messages (conversation_id, id);
CREATE INDEX chat_messages_thread ON chat_messages (thread_root_id, id)
    WHERE thread_root_id IS NOT NULL;
CREATE INDEX chat_messages_pins ON chat_messages (conversation_id, id)
    WHERE pinned_at IS NOT NULL;
CREATE INDEX chat_messages_threads ON chat_messages (conversation_id, last_reply_id)
    WHERE reply_count > 0;
CREATE UNIQUE INDEX chat_messages_nonce ON chat_messages (conversation_id, author_id, nonce)
    WHERE nonce IS NOT NULL;
CREATE TABLE chat_message_mentions (
    message_id TEXT NOT NULL REFERENCES chat_messages(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id),
    conversation_id TEXT NOT NULL,
    thread_root_id TEXT,
    -- The message shows in the main list (a root, or an "also in channel" reply).
    in_main BIGINT NOT NULL CHECK (in_main IN (0, 1)),
    PRIMARY KEY (message_id, user_id)
);
CREATE INDEX chat_message_mentions_user
    ON chat_message_mentions (user_id, conversation_id, message_id);
CREATE TABLE chat_reactions (
    message_id TEXT NOT NULL REFERENCES chat_messages(id) ON DELETE CASCADE,
    emoji TEXT NOT NULL CHECK (length(emoji) BETWEEN 1 AND 64),
    user_id TEXT NOT NULL REFERENCES users(id),
    created_at BIGINT NOT NULL,
    PRIMARY KEY (message_id, emoji, user_id)
);
CREATE TABLE chat_thread_members (
    root_id TEXT NOT NULL REFERENCES chat_messages(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL,
    workspace_id TEXT NOT NULL,
    conversation_id TEXT NOT NULL REFERENCES chat_conversations(id) ON DELETE CASCADE,
    following BIGINT NOT NULL CHECK (following IN (0, 1)),
    last_read_reply_id TEXT,
    read_reply_count BIGINT NOT NULL DEFAULT 0 CHECK (read_reply_count >= 0),
    mention_count BIGINT NOT NULL DEFAULT 0 CHECK (mention_count >= 0),
    PRIMARY KEY (root_id, user_id),
    FOREIGN KEY (workspace_id, user_id) REFERENCES memberships(workspace_id, user_id) ON DELETE CASCADE
);
CREATE INDEX chat_thread_members_user ON chat_thread_members (workspace_id, user_id, following);
CREATE INDEX chat_thread_members_conversation ON chat_thread_members (conversation_id, user_id);
CREATE FUNCTION chat_default_channel_for_member_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    -- UUIDv7 text from created_at (ms, 12+ hex digits) and 72 random bits, as in SQLite
    -- (printf('%012x', ...) and lower(hex(randomblob(9)))).
    INSERT INTO chat_conversations (id, workspace_id, kind, name, is_default, created_by,
                                    created_at, updated_at)
    SELECT
        substr(seed.ts, 1, 8) || '-' || substr(seed.ts, 9, 4) || '-7' || substr(seed.r, 1, 3) || '-'
            || substr('89ab', 1 + floor(random() * 4)::INT, 1) || substr(seed.r, 4, 3) || '-'
            || substr(seed.r, 7, 12),
        NEW.workspace_id,
        'public',
        'general',
        1,
        NEW.user_id,
        NEW.created_at,
        NEW.created_at
    FROM (
        SELECT lpad(to_hex(NEW.created_at), greatest(12, length(to_hex(NEW.created_at))), '0') AS ts,
               substr(replace(gen_random_uuid()::TEXT, '-', ''), 1, 12)
                   || substr(replace(gen_random_uuid()::TEXT, '-', ''), 1, 6) AS r
    ) AS seed
    WHERE NOT EXISTS (
        SELECT 1 FROM chat_conversations
        WHERE chat_conversations.workspace_id = NEW.workspace_id
          AND chat_conversations.is_default = 1
    );

    -- A member who joins starts with everything read.
    INSERT INTO chat_members (conversation_id, user_id, workspace_id, notify,
                              last_read_message_id, read_count, joined_at)
    SELECT chat_conversations.id, NEW.user_id, NEW.workspace_id, 'mentions',
           (SELECT chat_messages.id FROM chat_messages
            WHERE chat_messages.conversation_id = chat_conversations.id
            ORDER BY chat_messages.id COLLATE "C" DESC LIMIT 1),
           chat_conversations.message_count,
           NEW.created_at
    FROM chat_conversations
    WHERE chat_conversations.workspace_id = NEW.workspace_id
      AND chat_conversations.is_default = 1;
    RETURN NULL;
END;
$$;
CREATE TRIGGER chat_default_channel_for_member
    AFTER INSERT ON memberships
    FOR EACH ROW
    EXECUTE FUNCTION chat_default_channel_for_member_fn();
CREATE TABLE chat_message_files (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    -- Both NULL until the message is sent.
    message_id TEXT REFERENCES chat_messages(id) ON DELETE CASCADE,
    conversation_id TEXT REFERENCES chat_conversations(id) ON DELETE CASCADE,
    blob_id TEXT NOT NULL REFERENCES attachment_blobs(id) ON DELETE RESTRICT,
    file_name TEXT NOT NULL CHECK (length(file_name) BETWEEN 1 AND 255),
    -- Detected from the file's bytes.
    mime_type TEXT NOT NULL,
    size_bytes BIGINT NOT NULL CHECK (size_bytes >= 0),
    -- Of an image, as the uploader's browser measured it: only a hint to reserve space.
    width BIGINT CHECK (width IS NULL OR width BETWEEN 1 AND 100000),
    height BIGINT CHECK (height IS NULL OR height BETWEEN 1 AND 100000),
    uploaded_by TEXT NOT NULL REFERENCES users(id),
    created_at BIGINT NOT NULL,
    CHECK ((message_id IS NULL) = (conversation_id IS NULL))
);
CREATE INDEX chat_message_files_message ON chat_message_files (message_id);
CREATE INDEX chat_message_files_conversation ON chat_message_files (conversation_id, message_id);
CREATE INDEX chat_message_files_blob ON chat_message_files (blob_id);
CREATE INDEX chat_message_files_workspace ON chat_message_files (workspace_id);
CREATE INDEX chat_message_files_pending ON chat_message_files (created_at)
    WHERE message_id IS NULL;
CREATE FUNCTION chat_message_files_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM attachment_blobs
        WHERE attachment_blobs.id = NEW.blob_id AND attachment_blobs.workspace_id = NEW.workspace_id
    )
    THEN
        RAISE EXCEPTION 'chat file scope mismatch';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER chat_message_files_scope_insert
    BEFORE INSERT ON chat_message_files
    FOR EACH ROW
    EXECUTE FUNCTION chat_message_files_scope_insert_fn();
CREATE FUNCTION chat_message_files_scope_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'chat file scope is immutable';
END;
$$;
CREATE TRIGGER chat_message_files_scope_immutable
    BEFORE UPDATE OF workspace_id, blob_id ON chat_message_files
    FOR EACH ROW
    WHEN (NEW.workspace_id <> OLD.workspace_id OR NEW.blob_id <> OLD.blob_id)
    EXECUTE FUNCTION chat_message_files_scope_immutable_fn();
CREATE FUNCTION chat_message_files_quarantine_blob_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE attachment_blobs
    SET quarantine_until = GREATEST(
        quarantine_until,
        floor(EXTRACT(EPOCH FROM clock_timestamp()))::BIGINT * 1000 + 86400000
    )
    WHERE id = OLD.blob_id;
    RETURN NULL;
END;
$$;
CREATE TRIGGER chat_message_files_quarantine_blob
    AFTER DELETE ON chat_message_files
    FOR EACH ROW
    EXECUTE FUNCTION chat_message_files_quarantine_blob_fn();
-- SQLite: CREATE VIRTUAL TABLE chat_search USING fts5(body, content = 'chat_messages',
--     content_rowid = 'row_id', tokenize = 'unicode61 remove_diacritics 2').
-- Here the body is stored (rowid = chat_messages.row_id), kept in sync by the chat_search_* triggers.
CREATE TABLE chat_search (
    rowid BIGINT PRIMARY KEY,
    body TEXT,
    search_vector tsvector GENERATED ALWAYS AS (to_tsvector('orbit_search', regexp_replace(coalesce(body, ''), '[^[:alnum:]]+', ' ', 'g'))) STORED
);
CREATE INDEX chat_search_search_vector ON chat_search USING GIN (search_vector);
CREATE FUNCTION chat_search_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO chat_search (rowid, body) VALUES (NEW.row_id, NEW.body);
    RETURN NULL;
END;
$$;
CREATE TRIGGER chat_search_insert
    AFTER INSERT ON chat_messages
    FOR EACH ROW
    WHEN (NEW.kind = 'message')
    EXECUTE FUNCTION chat_search_insert_fn();
CREATE FUNCTION chat_search_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM chat_search WHERE rowid = OLD.row_id;
    INSERT INTO chat_search (rowid, body) VALUES (NEW.row_id, NEW.body);
    RETURN NULL;
END;
$$;
CREATE TRIGGER chat_search_update
    AFTER UPDATE OF body ON chat_messages
    FOR EACH ROW
    WHEN (NEW.kind = 'message' AND NEW.body IS DISTINCT FROM OLD.body)
    EXECUTE FUNCTION chat_search_update_fn();
CREATE FUNCTION chat_search_delete_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM chat_search WHERE rowid = OLD.row_id;
    RETURN NULL;
END;
$$;
CREATE TRIGGER chat_search_delete
    AFTER DELETE ON chat_messages
    FOR EACH ROW
    WHEN (OLD.kind = 'message')
    EXECUTE FUNCTION chat_search_delete_fn();
CREATE TABLE notifications (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    recipient_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    kind TEXT NOT NULL
        CHECK (kind IN ('task_assigned', 'comment_mentioned', 'page_comment_mentioned', 'page_mentioned',
                        'chat_mentioned')),
    task_id TEXT REFERENCES tasks(id) ON DELETE CASCADE,
    comment_id TEXT REFERENCES task_comments(id) ON DELETE CASCADE,
    page_id TEXT REFERENCES pages(id) ON DELETE CASCADE,
    page_thread_id TEXT REFERENCES page_threads(id) ON DELETE CASCADE,
    page_comment_id TEXT REFERENCES page_comments(id) ON DELETE CASCADE,
    page_block_id TEXT CHECK (page_block_id IS NULL OR length(page_block_id) BETWEEN 1 AND 64),
    chat_conversation_id TEXT REFERENCES chat_conversations(id) ON DELETE CASCADE,
    chat_message_id TEXT REFERENCES chat_messages(id) ON DELETE CASCADE,
    dedupe_key TEXT NOT NULL UNIQUE,
    read_at BIGINT,
    created_at BIGINT NOT NULL, pushed_at BIGINT,
    CHECK ((kind = 'chat_mentioned') = (chat_conversation_id IS NOT NULL)),
    CHECK ((chat_conversation_id IS NULL) = (chat_message_id IS NULL)),
    CHECK (
        (kind IN ('task_assigned', 'comment_mentioned')
            AND task_id IS NOT NULL
            AND page_id IS NULL AND page_thread_id IS NULL AND page_comment_id IS NULL
            AND page_block_id IS NULL)
        OR (kind = 'page_comment_mentioned'
            AND task_id IS NULL AND comment_id IS NULL
            AND page_id IS NOT NULL AND page_thread_id IS NOT NULL AND page_comment_id IS NOT NULL
            AND page_block_id IS NULL)
        OR (kind = 'page_mentioned'
            AND task_id IS NULL AND comment_id IS NULL
            AND page_id IS NOT NULL AND page_thread_id IS NULL AND page_comment_id IS NULL)
        OR (kind = 'chat_mentioned'
            AND task_id IS NULL AND comment_id IS NULL
            AND page_id IS NULL AND page_thread_id IS NULL AND page_comment_id IS NULL
            AND page_block_id IS NULL)
    )
);
CREATE INDEX notifications_inbox ON notifications (
    workspace_id,
    recipient_user_id,
    created_at,
    id
);
CREATE INDEX notifications_task ON notifications (task_id);
CREATE INDEX notifications_comment ON notifications (comment_id);
CREATE INDEX notifications_page ON notifications (page_id);
CREATE INDEX notifications_page_thread ON notifications (page_thread_id);
CREATE INDEX notifications_page_comment ON notifications (page_comment_id);
CREATE INDEX notifications_recipient ON notifications (recipient_user_id);
CREATE INDEX notifications_actor ON notifications (actor_user_id);
CREATE INDEX notifications_chat_message ON notifications (chat_message_id);
CREATE INDEX notifications_chat_unread ON notifications (chat_conversation_id, recipient_user_id)
    WHERE read_at IS NULL AND chat_conversation_id IS NOT NULL;
CREATE INDEX notifications_page_mentions ON notifications (page_id, recipient_user_id, created_at)
    WHERE kind = 'page_mentioned';
CREATE FUNCTION notifications_validate_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM memberships
        WHERE memberships.workspace_id = NEW.workspace_id
          AND memberships.user_id = NEW.recipient_user_id
    ) OR (
        NEW.task_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM tasks
            WHERE tasks.id = NEW.task_id AND tasks.workspace_id = NEW.workspace_id
        )
    ) OR (
        NEW.comment_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM task_comments
            WHERE task_comments.id = NEW.comment_id
              AND task_comments.task_id = NEW.task_id
              AND task_comments.workspace_id = NEW.workspace_id
        )
    ) OR (
        NEW.page_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM pages
            WHERE pages.id = NEW.page_id
              AND pages.workspace_id = NEW.workspace_id
              AND (pages.owner_id IS NULL OR pages.owner_id = NEW.recipient_user_id)
        )
    ) OR (
        NEW.chat_message_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM chat_messages
            JOIN chat_conversations ON chat_conversations.id = chat_messages.conversation_id
            WHERE chat_messages.id = NEW.chat_message_id
              AND chat_messages.conversation_id = NEW.chat_conversation_id
              AND chat_conversations.workspace_id = NEW.workspace_id
        )
    ) OR (
        NEW.page_comment_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM page_comments
            WHERE page_comments.id = NEW.page_comment_id
              AND page_comments.thread_id = NEW.page_thread_id
              AND page_comments.page_id = NEW.page_id
              AND page_comments.workspace_id = NEW.workspace_id
        )
    )
    THEN
        RAISE EXCEPTION 'notification must belong to the workspace task, a page the recipient can see or a chat message';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER notifications_validate_scope_insert
    BEFORE INSERT ON notifications
    FOR EACH ROW
    EXECUTE FUNCTION notifications_validate_scope_insert_fn();
CREATE UNIQUE INDEX tasks_project_number ON tasks (project_id, number);
CREATE FUNCTION tasks_number_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE projects SET task_counter = task_counter + 1 WHERE id = NEW.project_id;
    UPDATE tasks SET number = (SELECT task_counter FROM projects WHERE id = NEW.project_id)
    WHERE id = NEW.id;
    RETURN NULL;
END;
$$;
CREATE TRIGGER tasks_number_insert
    AFTER INSERT ON tasks
    FOR EACH ROW
    WHEN (NEW.number IS NULL)
    EXECUTE FUNCTION tasks_number_insert_fn();
CREATE FUNCTION tasks_number_insert_explicit_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE projects SET task_counter = GREATEST(task_counter, NEW.number) WHERE id = NEW.project_id;
    RETURN NULL;
END;
$$;
CREATE TRIGGER tasks_number_insert_explicit
    AFTER INSERT ON tasks
    FOR EACH ROW
    WHEN (NEW.number IS NOT NULL)
    EXECUTE FUNCTION tasks_number_insert_explicit_fn();
CREATE TABLE task_number_aliases (
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    number BIGINT NOT NULL CHECK (number > 0),
    task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    PRIMARY KEY (project_id, number)
);
CREATE INDEX task_number_aliases_task ON task_number_aliases (task_id);
CREATE FUNCTION tasks_number_project_change_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    -- SQLite: INSERT OR REPLACE (the primary key is the only unique constraint).
    IF OLD.number IS NOT NULL THEN
        INSERT INTO task_number_aliases (project_id, number, task_id)
        VALUES (OLD.project_id, OLD.number, OLD.id)
        ON CONFLICT (project_id, number) DO UPDATE SET task_id = EXCLUDED.task_id;
    END IF;
    UPDATE projects SET task_counter = task_counter + 1 WHERE id = NEW.project_id;
    UPDATE tasks SET number = (SELECT task_counter FROM projects WHERE id = NEW.project_id)
    WHERE id = NEW.id;
    RETURN NULL;
END;
$$;
CREATE TRIGGER tasks_number_project_change
    AFTER UPDATE OF project_id ON tasks
    FOR EACH ROW
    WHEN (NEW.project_id IS DISTINCT FROM OLD.project_id)
    EXECUTE FUNCTION tasks_number_project_change_fn();
CREATE TABLE user_status (
    user_id TEXT PRIMARY KEY REFERENCES users(id),
    presence TEXT NOT NULL CHECK (presence IN ('online', 'idle', 'dnd', 'invisible')),
    emoji TEXT CHECK (emoji IS NULL OR length(emoji) BETWEEN 1 AND 32),
    text TEXT CHECK (text IS NULL OR length(text) BETWEEN 1 AND 100),
    expires_at BIGINT,
    updated_at BIGINT NOT NULL,
    CHECK (expires_at IS NULL OR emoji IS NOT NULL OR text IS NOT NULL)
);
CREATE TABLE user_notes (
    author_id TEXT NOT NULL REFERENCES users(id),
    subject_id TEXT NOT NULL REFERENCES users(id),
    body TEXT NOT NULL CHECK (length(body) BETWEEN 1 AND 1000),
    updated_at BIGINT NOT NULL,
    PRIMARY KEY (author_id, subject_id)
);
CREATE TABLE push_subscriptions (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id),
    session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
    endpoint TEXT NOT NULL UNIQUE CHECK (length(endpoint) BETWEEN 1 AND 2048),
    p256dh TEXT NOT NULL CHECK (length(p256dh) BETWEEN 1 AND 200),
    auth TEXT NOT NULL CHECK (length(auth) BETWEEN 1 AND 100),
    -- What the user sees in the list of devices, e.g. "Firefox on Linux".
    label TEXT NOT NULL CHECK (length(label) <= 120),
    created_at BIGINT NOT NULL,
    -- How many pushes to it failed in a row. A push service that refuses the subscription again
    -- and again (not "gone", which removes it at once) will not take it later either: the server
    -- removes it after a few failures. A push that goes through sets the count back to zero.
    failures BIGINT NOT NULL DEFAULT 0 CHECK (failures >= 0)
);
CREATE INDEX push_subscriptions_user ON push_subscriptions (user_id);
CREATE INDEX push_subscriptions_session ON push_subscriptions (session_id);
CREATE TABLE notification_prefs (
    user_id TEXT PRIMARY KEY REFERENCES users(id),
    direct_messages BIGINT NOT NULL DEFAULT 1 CHECK (direct_messages IN (0, 1)),
    chat_mentions BIGINT NOT NULL DEFAULT 1 CHECK (chat_mentions IN (0, 1)),
    thread_replies BIGINT NOT NULL DEFAULT 1 CHECK (thread_replies IN (0, 1)),
    -- Every message of a channel whose notify level is `all`.
    channel_messages BIGINT NOT NULL DEFAULT 1 CHECK (channel_messages IN (0, 1)),
    task_assigned BIGINT NOT NULL DEFAULT 1 CHECK (task_assigned IN (0, 1)),
    -- Mentions in task comments, pages and page comments.
    mentions BIGINT NOT NULL DEFAULT 1 CHECK (mentions IN (0, 1)),
    updated_at BIGINT NOT NULL
);
CREATE TABLE push_keys (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (id = 1),
    private_key BYTEA NOT NULL CHECK (octet_length(private_key) = 32),
    created_at BIGINT NOT NULL
);
CREATE INDEX notifications_unpushed ON notifications (id) WHERE pushed_at IS NULL;
CREATE TABLE instance_settings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (id = 1),
    registration_open BIGINT NOT NULL DEFAULT 0 CHECK (registration_open IN (0, 1)),
    smtp_host TEXT CHECK (smtp_host IS NULL OR length(smtp_host) BETWEEN 1 AND 253),
    smtp_port BIGINT CHECK (smtp_port IS NULL OR smtp_port BETWEEN 1 AND 65535),
    smtp_security TEXT CHECK (smtp_security IS NULL OR smtp_security IN ('tls', 'starttls', 'none')),
    smtp_username TEXT CHECK (smtp_username IS NULL OR length(smtp_username) BETWEEN 1 AND 320),
    -- ChaCha20-Poly1305 under the server app key (secret_box.rs), never plain text.
    smtp_password BYTEA,
    smtp_from_address TEXT CHECK (smtp_from_address IS NULL OR length(smtp_from_address) BETWEEN 3 AND 320),
    smtp_from_name TEXT CHECK (smtp_from_name IS NULL OR length(smtp_from_name) BETWEEN 1 AND 120),
    updated_at BIGINT NOT NULL, s3_endpoint TEXT
    CHECK (s3_endpoint IS NULL OR length(s3_endpoint) BETWEEN 8 AND 2048), s3_region TEXT
    CHECK (s3_region IS NULL OR length(s3_region) BETWEEN 1 AND 64), s3_bucket TEXT
    CHECK (s3_bucket IS NULL OR length(s3_bucket) BETWEEN 3 AND 63), s3_prefix TEXT NOT NULL DEFAULT ''
    CHECK (length(s3_prefix) <= 512), s3_access_key_id TEXT
    CHECK (s3_access_key_id IS NULL OR length(s3_access_key_id) BETWEEN 1 AND 256), s3_secret_access_key BYTEA, s3_path_style BIGINT NOT NULL DEFAULT 0
    CHECK (s3_path_style IN (0, 1)), attachments_in_s3 BIGINT NOT NULL DEFAULT 0
    CHECK (attachments_in_s3 IN (0, 1)), backups_in_s3 BIGINT NOT NULL DEFAULT 0
    CHECK (backups_in_s3 IN (0, 1)), backup_schedule TEXT NOT NULL DEFAULT 'off'
    CHECK (backup_schedule IN ('off', 'hourly', 'daily')),
    -- SMTP is configured exactly when host, port, security and sender are all set.
    CHECK (
        (smtp_host IS NULL AND smtp_port IS NULL AND smtp_security IS NULL AND smtp_from_address IS NULL)
        OR (smtp_host IS NOT NULL AND smtp_port IS NOT NULL AND smtp_security IS NOT NULL
            AND smtp_from_address IS NOT NULL)
    )
);
CREATE TABLE registration_tokens (
    token_hash BYTEA PRIMARY KEY CHECK (octet_length(token_hash) = 32),
    normalized_email TEXT NOT NULL,
    expires_at BIGINT NOT NULL,
    created_at BIGINT NOT NULL
);
CREATE INDEX registration_tokens_expiry ON registration_tokens (expires_at);
CREATE INDEX registration_tokens_email ON registration_tokens (normalized_email);
CREATE TABLE user_totp (
    user_id TEXT PRIMARY KEY REFERENCES users(id),
    secret BYTEA NOT NULL,
    enabled_at BIGINT,
    last_used_step BIGINT NOT NULL DEFAULT 0 CHECK (last_used_step >= 0),
    created_at BIGINT NOT NULL
);
CREATE TABLE user_recovery_codes (
    user_id TEXT NOT NULL REFERENCES users(id),
    code_hash BYTEA NOT NULL CHECK (octet_length(code_hash) = 32),
    created_at BIGINT NOT NULL,
    PRIMARY KEY (user_id, code_hash)
);
CREATE TABLE user_passkeys (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id),
    -- base64url, as the browser sends it back when signing in.
    credential_id TEXT NOT NULL UNIQUE CHECK (length(credential_id) BETWEEN 1 AND 1400),
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 64),
    passkey TEXT NOT NULL,
    created_at BIGINT NOT NULL,
    last_used_at BIGINT
);
CREATE INDEX user_passkeys_user ON user_passkeys (user_id);
CREATE TABLE user_avatars (
    user_id TEXT PRIMARY KEY REFERENCES users(id),
    mime_type TEXT NOT NULL CHECK (mime_type IN ('image/png', 'image/jpeg', 'image/webp')),
    bytes BYTEA CHECK (octet_length(bytes) BETWEEN 1 AND 524288),
    blob_id TEXT REFERENCES attachment_blobs(id) ON DELETE RESTRICT,
    updated_at BIGINT NOT NULL,
    CHECK ((bytes IS NULL) <> (blob_id IS NULL))
);
CREATE INDEX user_avatars_blob ON user_avatars (blob_id);
CREATE TABLE custom_emoji (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name TEXT NOT NULL CHECK (length(name) BETWEEN 2 AND 32 AND name !~ '^.*[^a-z0-9_].*$' /* was: name NOT GLOB '*[^a-z0-9_]*' */),
    mime_type TEXT NOT NULL CHECK (mime_type IN ('image/png', 'image/jpeg', 'image/webp', 'image/gif')),
    bytes BYTEA CHECK (octet_length(bytes) BETWEEN 1 AND 262144),
    blob_id TEXT REFERENCES attachment_blobs(id) ON DELETE RESTRICT,
    created_by TEXT NOT NULL REFERENCES users(id),
    created_at BIGINT NOT NULL,
    -- Also the index of the list of a workspace, which is ordered by name.
    UNIQUE (workspace_id, name),
    CHECK ((bytes IS NULL) <> (blob_id IS NULL))
);
CREATE INDEX custom_emoji_blob ON custom_emoji (blob_id);
CREATE TABLE custom_stickers (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name TEXT NOT NULL /* SQLite: COLLATE NOCASE */ CHECK (length(name) BETWEEN 2 AND 30),
    mime_type TEXT NOT NULL CHECK (mime_type IN ('image/png', 'image/jpeg', 'image/webp', 'image/gif')),
    bytes BYTEA CHECK (octet_length(bytes) BETWEEN 1 AND 524288),
    blob_id TEXT REFERENCES attachment_blobs(id) ON DELETE RESTRICT,
    created_by TEXT NOT NULL REFERENCES users(id),
    created_at BIGINT NOT NULL,
    -- Also the index of the list of a workspace, which is ordered by name.
    -- SQLite: UNIQUE (workspace_id, name) under NOCASE -> custom_stickers_workspace_id_name_key below.
    CHECK ((bytes IS NULL) <> (blob_id IS NULL))
);
CREATE UNIQUE INDEX custom_stickers_workspace_id_name_key
    ON custom_stickers (workspace_id, lower(name));
CREATE INDEX custom_stickers_blob ON custom_stickers (blob_id);

